# #816 (TJ Oct 28 2026): welcome hologram must play all sentences (~20 s) unless Skip. Keeps #815 tour route, #814 holos-off gate.
# Idempotent; asserts nest 815 or 816; backs up once to /tmp/*.815.
import json, os, shutil
F='src/catalog.json'
for s,d in ((F,'/tmp/catalog.json.815'),('deploy/execute.js','/tmp/execute.js.815'),('src/tour.js','/tmp/tour.js.815')):
    if not os.path.exists(d): shutil.copy(s,d)
assert 'index-Ba9lwWP_.js' in open('/tmp/execute.js.815').read(), 'rollback backup is not #815'
c=json.load(open(F)); T=c['layout']['tags']; assert T['nest']['issue'] in (815,816), T['nest']
T['nest'].update(issue=816,prev=815,note816='#816 welcome hologram plays through (~20 s): iOS unmuted unlock in the tap, no unmute-without-gesture, paused-video retry + wall-clock captions, Skip really stops it; #815 route + #814 holos-off kept')
open(F,'w').write(json.dumps(c,ensure_ascii=False,separators=(',',':')))
t=open('src/tour.js').read()
if 'welcomeGuard' not in t:
    for x,y in json.loads('[["  let primed = false; const prime = () => { if (primed) return; primed = true; for (const m of [audio, video]) { try { const was = m.muted; m.muted = true; const p = m.play(); if (p) p.then(() => { if (S.phase === \'wait\') m.pause(); m.muted = was; }).catch(() => { m.muted = was; }); } catch (e) {} } };", "  let primed = false; const prime = () => { if (primed) return; primed = true; const g0 = SP.pa[1]; try { if (g0) g0.setVolume(0); } catch (e) {} for (const m of [audio, video]) { try { const was = m.muted; m.muted = !(m === video && g0); /* #816: iOS unlock needs an unmuted play in the gesture; routed through a zero gain so nothing is heard */ const p = m.play(); if (p) p.then(() => { if (S.phase === \'wait\') m.pause(); m.muted = was; if (m === video) try { g0 && g0.setVolume(1); } catch (e) {} }).catch(() => { m.muted = was; try { g0 && g0.setVolume(1); } catch (e) {} }); } catch (e) {} } };"], ["    setCues(WELCOME); video.muted = muted(); video.currentTime = 0; video.playbackRate = RATE; const pr = video.play(); if (pr) pr.catch(() => { video.muted = true; video.play().catch(() => { S.videoFail = true; }); });", "    setCues(WELCOME); video.muted = muted(); video.currentTime = 0; video.playbackRate = RATE; try { SP.pa[1] && SP.pa[1].setVolume(1); } catch (e) {} S.vMute = false; S.vLog = []; const pr = video.play(); if (pr) pr.catch(() => { S.vMute = true; S.vLog.push(\'mutedplay\'); video.muted = true; video.play().catch(() => { S.videoFail = true; }); }); /* #816 */"], ["  function toOffer(skipped) { if (S.phase !== \'welcome\') return; S.skipped = !!skipped; S.phase = \'offer\'; skip.style.display = \'none\'; freeze(true); if (document.pointerLockElement) try { document.exitPointerLock(); } catch (e) {} // #348: the offer panel needs the cursor if (holo) holo.out = true; try { video.pause(); } catch (e) {}", "  function toOffer(skipped) { if (S.phase !== \'welcome\') return; S.skipped = !!skipped; S.phase = \'offer\'; skip.style.display = \'none\'; freeze(true); if (document.pointerLockElement) try { document.exitPointerLock(); } catch (e) {} /* #348: the offer panel needs the cursor */ if (holo) holo.out = true; try { video.pause(); } catch (e) {} // #816: was inside the comment, so the welcome kept playing after Skip"], ["  document.addEventListener(\'pointerlockchange\', () => { if (!document.pointerLockElement && S.phase === \'welcome\' && !touch) toOffer(true); }); // #348: Esc that only drops the lock = skip, never a PAUSED screen mid-welcome", "  // #816 (TJ: welcome cut off after the first sentence): the welcome only ends at the clip end or Skip. If the browser pauses the video\\n  // mid-welcome (iOS unmute without a gesture, another media session, a stall), retry it, and the next tap resumes it with sound;\\n  // if it cannot play, captions run on the wall clock to the end instead of freezing.\\n  function welcomeGuard(now) { if (S.skipped) return; const t = video.currentTime || 0;\\n    if (video.paused && !video.ended && !S.videoFail) { S.vPausedAt = S.vPausedAt || now; if (now - (S.vRetry || 0) > 700) { S.vRetry = now; S.vLog.push(\'retry@\' + t.toFixed(1)); const q = video.play(); if (q) q.catch(() => { if (!S.vMute) { S.vMute = true; video.muted = true; video.play().catch(() => {}); } }); }\\n      if (now - S.vPausedAt > 2500) { S.videoFail = true; S.wallFrom = now - t * 1000 / RATE; S.vLog.push(\'wallclock@\' + t.toFixed(1)); } } else S.vPausedAt = 0; }\\n  const welcomeTap = () => { if (S.phase !== \'welcome\') return; if (S.vMute && !muted()) { S.vMute = false; video.muted = false; S.vLog.push(\'unmute-tap\'); } if (video.paused && !video.ended) { if (S.videoFail && S.wallFrom) { try { video.currentTime = Math.min(WELCOME_END_S, (performance.now() - S.wallFrom) / 1000 * RATE); } catch (e) {} } video.play().then(() => { S.videoFail = false; S.wallFrom = 0; }).catch(() => {}); } };\\n  [\'pointerup\', \'touchend\', \'keydown\'].forEach(n => addEventListener(n, welcomeTap, { capture: true, passive: true }));\\n  document.addEventListener(\'pointerlockchange\', () => { if (!document.pointerLockElement && S.phase === \'welcome\' && !touch) toOffer(true); }); // #348: Esc that only drops the lock = skip, never a PAUSED screen mid-welcome"], ["    audio.muted = muted(); video.muted = muted() || video.muted && S.videoFail; spatialTick();", "    audio.muted = muted(); video.muted = muted() || S.vMute || video.muted && S.videoFail; spatialTick(); if (S.phase === \'welcome\') welcomeGuard(now);"], ["    if (S.phase === \'welcome\') { showCue(video.currentTime || 0); if (video.ended || (S.videoFail && now - S.t0 > WELCOME_END_MS / RATE) || video.currentTime >= WELCOME_END_S) /* #799 */ toOffer(false); return; }", "    if (S.phase === \'welcome\') { const wt = S.videoFail && S.wallFrom ? (now - S.wallFrom) / 1000 * RATE : video.currentTime || 0; showCue(wt); if (video.ended || (S.videoFail && (S.wallFrom ? wt >= WELCOME_END_S : now - S.t0 > WELCOME_END_MS / RATE)) || video.currentTime >= WELCOME_END_S) /* #799, #816 wall clock if the video stalls */ toOffer(false); return; }"]]'):
        assert t.count(x)==1, x[:80]; t=t.replace(x,y)
    open('src/tour.js','w').write(t)
print(816,T['nest'])
